//! Owned-trial analysis pipeline. Caller must establish exclusive path and DB authority.
use super::{csdm_analysis::{Analyses,Claim},csdm_analyzer::{self,Request},csdm_import,csdm_match_readback};
use postgres::Client;
use serde_json::{json,Value};
use std::{cell::Cell,path::Path,sync::{mpsc,Mutex,TryLockError},thread,time::{Duration,Instant}};
#[derive(Debug)] pub enum Outcome {InvalidClaim,DuplicateExecution,StateUnavailable,AnalyzerFailed(String),CorruptedUnsupported,ImportFailed{message:String,commit_may_have_occurred:bool},DeliveryFailed{message:String,commit_may_have_occurred:bool},Inserted(Value)}
thread_local!{static PUBLISHING:Cell<bool>=const{Cell::new(false)};}struct PublishingReset;impl Drop for PublishingReset{fn drop(&mut self){PUBLISHING.with(|v|v.set(false));}}
/// One ordering gate covers mutation and publication. Queue state is unlocked before callbacks;
/// same-thread reentry returns an error instead of waiting on the gate it already owns.
pub(super) fn ordered<T>(state:&Mutex<Analyses>,order:&Mutex<()>,change:impl FnOnce(&mut Analyses)->Result<(T,Option<Value>),String>,emit:&mut impl FnMut(Value)->Result<(),String>)->Result<T,String>{if PUBLISHING.with(|v|v.get()){return Err("Reentrant analysis publication".into())}let deadline=Instant::now()+Duration::from_secs(2);let _permit=loop{match order.try_lock(){Ok(guard)=>break guard,Err(TryLockError::Poisoned(_))=>return Err("Analysis event ordering is unavailable".into()),Err(TryLockError::WouldBlock)=>{if Instant::now()>=deadline{return Err("Analysis event ordering timed out".into())}thread::sleep(Duration::from_millis(2));}}};PUBLISHING.with(|v|v.set(true));let _reset=PublishingReset;let (result,event)={let mut guard=state.lock().map_err(|_|"Analysis state is unavailable".to_string())?;change(&mut guard)?};if let Some(event)=event{emit(event)?}Ok(result)}
// Socket identities are minted by the transport. Close tombstones before awaiting the ordering gate.
pub(super) fn cli_connected(state:&Mutex<Analyses>,order:&Mutex<()>,id:&str)->Result<(),String>{ordered(state,order,|s|{s.connect_client(id)?;Ok(((),None))},&mut |_|Ok(()))}
pub(super) fn cli_enqueue(state:&Mutex<Analyses>,order:&Mutex<()>,id:&str,demos:Vec<Value>,positions:Option<bool>,mut now:impl FnMut()->String,emit:&mut impl FnMut(Value)->Result<(),String>)->Result<(bool,bool),String>{ordered(state,order,|s|{if !s.client_connected(id){return Ok(((false,false),None))}let event=s.add(demos,Some(id),positions,&mut now)?;let new_work=event.is_some();Ok(((true,new_work),event))},emit)}
pub(super) fn cli_disconnected(state:&Mutex<Analyses>,order:&Mutex<()>,id:&str,emit:&mut impl FnMut(Value)->Result<(),String>)->Result<(),String>{{state.lock().map_err(|_|"Analysis state is unavailable".to_string())?.mark_client_closed(id);}ordered(state,order,|s|Ok(((),s.close_client(id))),emit)}
pub(super) fn finish(state:&Mutex<Analyses>,order:&Mutex<()>,id:u64)->Result<(),String>{ordered(state,order,|s|{s.finish(id);Ok(((),None))},&mut |_|Ok(()))}
pub(super) fn finish_checked(state:&Mutex<Analyses>,order:&Mutex<()>,id:u64,may_commit:bool)->Result<(),Outcome>{finish(state,order,id).map_err(|e|Outcome::DeliveryFailed{message:format!("Analysis state cleanup unconfirmed: {e}"),commit_may_have_occurred:may_commit})}
pub(super) fn update(state:&Mutex<Analyses>,order:&Mutex<()>,id:u64,status:&str,emit:&mut impl FnMut(Value)->Result<(),String>)->Result<(),String>{ordered(state,order,|s|Ok(((),s.set_running_status(id,status).map(|v|json!({"name":"analysis-status-changed","payload":v})))),emit)}
fn append(state:&Mutex<Analyses>,order:&Mutex<()>,id:u64,text:&str,emit:&mut impl FnMut(Value)->Result<(),String>)->Result<(),String>{ordered(state,order,|s|Ok(((),s.append_output(id,text).map(|v|json!({"name":"analysis-status-changed","payload":v})))),emit)}
fn positions_match(value:Option<&Value>,actual:bool)->bool{match value{None|Some(Value::Null)=>true,Some(Value::Bool(v))=>*v==actual,Some(_)=>false}}
fn identity_matches(claim:&Claim,request:&Request,root:&Path,prefix:&str,checksum:&str)->bool{let Some(path)=request.demo.to_str() else{return false};let Some(stem)=request.demo.file_stem().and_then(|s|s.to_str()) else{return false};!checksum.is_empty()&&claim.analysis["demoChecksum"].as_str()==Some(checksum)&&claim.analysis["demoPath"].as_str()==Some(path)&&claim.analysis["source"].as_str()==Some(request.source.as_str())&&request.output==root&&stem==prefix&&positions_match(claim.analysis.get("analyzePositions"),request.positions)}
#[cfg(test)]fn valid_claim(state:&Analyses,claim:&Claim,request:&Request,root:&Path,prefix:&str,checksum:&str)->bool{state.owns_claim(claim)&&identity_matches(claim,request,root,prefix,checksum)}
// Mirrors the original current-length comparison to Math.min(8, numeric ?? 4).
pub(super) fn concurrency_limit(settings:&Value)->Result<usize,String>{let analyze=settings.get("analyze").filter(|x|x.is_object()).ok_or("Missing analyze settings")?;let n=match analyze.get("maxConcurrentAnalyses"){None|Some(Value::Null)=>4.0,Some(Value::Number(n))=>n.as_f64().ok_or("Invalid concurrency number")?,_=>return Err("Unsupported concurrency setting type".into())};if n<=0.0{Ok(0)}else{Ok(n.min(8.0).ceil() as usize)}}
pub(super) fn claim_and_start(state:&Mutex<Analyses>,order:&Mutex<()>,max:usize,emit:&mut impl FnMut(Value)->Result<(),String>)->Result<Option<Claim>,String>{let mut started=None;let result=ordered(state,order,|s|{let Some(mut claim)=s.claim(max) else{return Ok((None,None))};if !s.begin_claim(&claim){return Err("Could not start analysis claim".into())}started=Some(claim.run_id);let value=s.set_running_status(claim.run_id,"analyzing").ok_or("Analysis claim disappeared")?;claim.analysis=value.clone();Ok((Some(claim),Some(json!({"name":"analysis-status-changed","payload":value}))))},emit);if let Err(error)=result {if let Some(id)=started{if let Err(cleanup)=finish(state,order,id){return Err(format!("{error}; analysis state cleanup unconfirmed: {cleanup}"))}}return Err(error)}result}
pub(super) fn preparation_failure(state:&Mutex<Analyses>,order:&Mutex<()>,id:u64,message:&str,emit:&mut impl FnMut(Value)->Result<(),String>)->Result<(),String>{append(state,order,id,message,emit)?;update(state,order,id,"analyze-error",emit)?;finish(state,order,id)?;Ok(())}
fn import_failure(state:&Mutex<Analyses>,order:&Mutex<()>,id:u64,message:String,emit:&mut impl FnMut(Value)->Result<(),String>)->Outcome{if let Err(e)=append(state,order,id,&message,emit){return Outcome::DeliveryFailed{message:e,commit_may_have_occurred:true}}if let Err(e)=update(state,order,id,"insert-error",emit){return Outcome::DeliveryFailed{message:e,commit_may_have_occurred:true}}Outcome::ImportFailed{message,commit_may_have_occurred:true}}
pub fn run_claimed_no_key_fixture(state:&Mutex<Analyses>,order:&Mutex<()>,claim:Claim,request:&Request,client:&mut Client,root:&Path,prefix:&str,checksum:&str,mut emit:impl FnMut(Value)->Result<(),String>)->Outcome{
 let id=claim.run_id;let outcome=run_claimed_body(state,order,claim,request,client,root,prefix,checksum,None,&mut false,&mut emit);finalize(state,order,id,outcome)
}
pub(super) fn run_claimed_serial_import(state:&Mutex<Analyses>,order:&Mutex<()>,claim:Claim,request:&Request,client:&mut Client,root:&Path,prefix:&str,checksum:&str,gate:&Mutex<bool>,mut emit:impl FnMut(Value)->Result<(),String>)->Outcome{let id=claim.run_id;let mut finalized=false;let outcome=run_claimed_body(state,order,claim,request,client,root,prefix,checksum,Some(gate),&mut finalized,&mut emit);if finalized{outcome}else{finalize(state,order,id,outcome)}}
fn finalize(state:&Mutex<Analyses>,order:&Mutex<()>,id:u64,outcome:Outcome)->Outcome{if matches!(outcome,Outcome::InvalidClaim|Outcome::DuplicateExecution|Outcome::StateUnavailable){return outcome}let may_commit=matches!(&outcome,Outcome::Inserted(_)|Outcome::ImportFailed{commit_may_have_occurred:true,..}|Outcome::DeliveryFailed{commit_may_have_occurred:true,..});match finish_checked(state,order,id,may_commit){Ok(())=>outcome,Err(cleanup)=>cleanup}}
pub(super) fn acquire_execution(state:&Mutex<Analyses>,claim:&Claim)->Result<(),Outcome>{let mut s=state.lock().map_err(|_|Outcome::StateUnavailable)?;if !s.owns_started_claim(claim){return Err(Outcome::InvalidClaim)}if !s.begin_execution(claim){return Err(Outcome::DuplicateExecution)}Ok(())}
// The gate remains held through write/readback and direct event publication. If an
// outcome might have committed, later imports are refused rather than blindly retried.
fn guarded_import(gate:Option<&Mutex<bool>>,operation:impl FnOnce()->Outcome)->Outcome{match gate{None=>operation(),Some(g)=>{let mut unsafe_to_write=match g.lock(){Ok(guard)=>guard,Err(_)=>return Outcome::ImportFailed{message:"Owned import lock unavailable; write outcome unknown".into(),commit_may_have_occurred:true}};if *unsafe_to_write{return Outcome::ImportFailed{message:"Earlier owned import outcome uncertain; later write refused".into(),commit_may_have_occurred:false}}let result=operation();if matches!(&result,Outcome::ImportFailed{commit_may_have_occurred:true,..}|Outcome::DeliveryFailed{commit_may_have_occurred:true,..}){*unsafe_to_write=true}result}}}
fn run_claimed_body(state:&Mutex<Analyses>,order:&Mutex<()>,claim:Claim,request:&Request,client:&mut Client,root:&Path,prefix:&str,checksum:&str,gate:Option<&Mutex<bool>>,finalized:&mut bool,mut emit:impl FnMut(Value)->Result<(),String>)->Outcome{
 let id=claim.run_id;if !identity_matches(&claim,request,root,prefix,checksum){return Outcome::InvalidClaim}if let Err(outcome)=acquire_execution(state,&claim){return outcome}
 let(tx,rx)=mpsc::sync_channel(64);let mut delivery=None;let result=thread::scope(|scope|{let worker=scope.spawn(||csdm_analyzer::analyze(request,tx));for event in rx{if delivery.is_none(){if let Err(e)=append(state,order,id,&event.text,&mut emit){delivery=Some(e)}}}worker.join().unwrap_or(Err(csdm_analyzer::AnalyzerError::JobThreadPanic{cleanup_confirmed:None}))});
 if let Some(message)=delivery{return Outcome::DeliveryFailed{message,commit_may_have_occurred:false}}
 if let Err(error)=result{let corrupted=matches!(error,csdm_analyzer::AnalyzerError::Corrupted);let text=format!("{error:?}");if let Err(message)=append(state,order,id,&text,&mut emit){return Outcome::DeliveryFailed{message,commit_may_have_occurred:false}}if let Err(message)=update(state,order,id,"analyze-error",&mut emit){return Outcome::DeliveryFailed{message,commit_may_have_occurred:false}}return if corrupted{Outcome::CorruptedUnsupported}else{Outcome::AnalyzerFailed(text)}}
 for status in ["analyze-success","inserting-match"]{if let Err(message)=update(state,order,id,status,&mut emit){return Outcome::DeliveryFailed{message,commit_may_have_occurred:false}}}
 guarded_import(gate,||{let outcome=(||{
 if let Err(error)=csdm_import::import_match(client,root,prefix,checksum){return import_failure(state,order,id,format!("{error:?}"),&mut emit)}
 let match_value=match csdm_match_readback::fetch(client,checksum){Ok(v)=>v,Err(message)=>{if let Err(delivery)=update(state,order,id,"insert-error",&mut emit){return Outcome::DeliveryFailed{message:format!("{message}; error event failed: {delivery}"),commit_may_have_occurred:true}}return Outcome::ImportFailed{message,commit_may_have_occurred:true}}};
 if let Err(message)=update(state,order,id,"insert-success",&mut emit){return Outcome::DeliveryFailed{message,commit_may_have_occurred:true}}
 if let Err(message)=ordered(state,order,|_|Ok(((),Some(json!({"name":"match-inserted","payload":match_value.clone()})))),&mut emit){return Outcome::DeliveryFailed{message,commit_may_have_occurred:true}}
 Outcome::Inserted(match_value)
 })();if gate.is_some(){*finalized=true;finalize(state,order,id,outcome)}else{outcome}
 })
}

fn outcome_summary(value:&Outcome)->&'static str{match value{Outcome::Inserted(_)=>"inserted",Outcome::AnalyzerFailed(_)=>"analysis-failed",Outcome::CorruptedUnsupported=>"corrupted-unsupported",Outcome::InvalidClaim=>"invalid-claim",Outcome::DuplicateExecution=>"duplicate-execution",Outcome::StateUnavailable=>"state-unavailable",Outcome::ImportFailed{commit_may_have_occurred:true,..}|Outcome::DeliveryFailed{commit_may_have_occurred:true,..}=>"commit-possibly-occurred",Outcome::ImportFailed{..}=>"import-not-committed",Outcome::DeliveryFailed{..}=>"delivery-failed-before-import"}}
// Single outer driver owns refill. A worker implementation is responsible for
// finalizing its own claim exactly once before returning its connection.
pub(super) fn drive_refill<C:Send,T:Send,E:FnMut(Value)->Result<(),String>+Send,P:FnMut(&Claim,&Mutex<bool>)->Result<T,String>,W:Fn(Claim,T,&mut C,&Mutex<bool>,&Mutex<E>)->Outcome+Sync,L:FnMut()->Result<usize,String>,A:FnMut(String,&Mutex<E>)->String>(state:&Mutex<Analyses>,order:&Mutex<()>,slots:usize,mut free:Vec<C>,emit:E,mut read_limit:L,mut prepare:P,worker:W,mut abort:A)->Result<Value,String>{
 drive_refill_with_settings(state,order,slots,free,emit,||read_limit().map(|n|(n,Value::Null)),|claim,gate,_|prepare(claim,gate),worker,abort)
}
pub(super) fn drive_refill_with_settings<C:Send,T:Send,E:FnMut(Value)->Result<(),String>+Send,P:FnMut(&Claim,&Mutex<bool>,&Value)->Result<T,String>,W:Fn(Claim,T,&mut C,&Mutex<bool>,&Mutex<E>)->Outcome+Sync,L:FnMut()->Result<(usize,Value),String>,A:FnMut(String,&Mutex<E>)->String>(state:&Mutex<Analyses>,order:&Mutex<()>,slots:usize,mut free:Vec<C>,emit:E,mut read_limit:L,mut prepare:P,worker:W,mut abort:A)->Result<Value,String>{
 let sink=Mutex::new(emit);let import_gate=Mutex::new(false);
 std::thread::scope(|scope|{let(tx,rx)=std::sync::mpsc::channel();let mut active=0usize;let mut errors=Vec::<String>::new();let mut summaries=Vec::<&'static str>::new();
  loop{let pending=match state.lock(){Ok(s)=>s.has_pending(),Err(_)=>{errors.push("Analysis state unavailable".into());false}};let (max,snapshot)=if errors.is_empty()&&pending{match read_limit(){Ok((n,v)) if n<=slots=>(n,v),Ok(_)=>{errors.push("Settings exceed worker capacity".into());(0,Value::Null)},Err(e)=>{errors.push(format!("Settings reread failed: {e}"));(0,Value::Null)}}}else{(0,Value::Null)};while errors.is_empty()&&active<max{let gate_guard=match import_gate.lock(){Ok(g)=>g,Err(_)=>{errors.push("Owned import state unavailable; commit outcome unknown".into());break}};if *gate_guard{errors.push("Earlier owned worker outcome uncertain; refill stopped".into());break}let claim=match claim_and_start(state,order,max,&mut |e|sink.lock().map_err(|_|"Owned event sink unavailable".to_string())?(e)){Ok(Some(c))=>c,Ok(None)=>break,Err(e)=>{errors.push(e);break}};drop(gate_guard);let id=claim.run_id;let value=match prepare(&claim,&import_gate,&snapshot){Ok(v)=>v,Err(e)=>{if let Err(delivery)=preparation_failure(state,order,id,&e,&mut |event|sink.lock().map_err(|_|"Owned event sink unavailable".to_string())?(event)){errors.push(format!("{e}; preparation error delivery failed: {delivery}"));if let Err(cleanup)=finish(state,order,id){errors.push(format!("Unstarted worker cleanup unconfirmed: {cleanup}"))}}else{errors.push(e)}break}};
   let launch_gate=match import_gate.lock(){Ok(g)=>g,Err(_)=>{errors.push("Owned import state unavailable before launch; commit outcome unknown".into());if let Err(cleanup)=finish(state,order,id){errors.push(format!("Unstarted cleanup unconfirmed: {cleanup}"))}break}};if *launch_gate{drop(launch_gate);let message="Earlier owned worker outcome uncertain; prepared worker not launched".to_string();if let Err(delivery)=preparation_failure(state,order,id,&message,&mut |event|sink.lock().map_err(|_|"Owned event sink unavailable".to_string())?(event)){errors.push(format!("{message}; error delivery failed: {delivery}"));if let Err(cleanup)=finish(state,order,id){errors.push(format!("Unstarted cleanup unconfirmed: {cleanup}"))}}else{errors.push(message)}break}let Some(mut conn)=free.pop()else{drop(launch_gate);errors.push("Owned worker connection unavailable".into());if let Err(cleanup)=finish(state,order,id){errors.push(format!("Unstarted cleanup unconfirmed: {cleanup}"))}break};let sink_ref=&sink;let gate=&import_gate;let tx=tx.clone();let run=&worker;match std::thread::Builder::new().spawn_scoped(scope,move||{let outcome=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||run(claim,value,&mut conn,gate,sink_ref))).unwrap_or(Outcome::DeliveryFailed{message:"Owned worker panicked; cleanup unconfirmed".into(),commit_may_have_occurred:true});if !matches!(outcome,Outcome::Inserted(_)|Outcome::AnalyzerFailed(_)){if let Ok(mut stopped)=gate.lock(){*stopped=true}}let _=tx.send((outcome,conn));}){Ok(_)=>active+=1,Err(e)=>{let message=format!("Owned worker spawn failed: {e}");if let Err(delivery)=preparation_failure(state,order,id,&message,&mut |event|sink.lock().map_err(|_|"Owned event sink unavailable".to_string())?(event)){errors.push(format!("{message}; delivery failed: {delivery}"));if let Err(cleanup)=finish(state,order,id){errors.push(format!("Unstarted cleanup unconfirmed: {cleanup}"))}}else{errors.push(message)}break}}drop(launch_gate);
  }if active==0{if state.lock().map_err(|_|"Analysis state unavailable".to_string())?.cli_close_blocked(){return Err(format!("CLI close reconciliation pending; queue retained; errors: {}; completed worker outcomes: {}; commit may have occurred",errors.join("; "),summaries.join(",")))}break}let(outcome,conn)=rx.recv().map_err(|_|"Owned worker completion unavailable; commit outcome unknown".to_string())?;active-=1;free.push(conn);summaries.push(outcome_summary(&outcome));if !matches!(outcome,Outcome::Inserted(_)|Outcome::AnalyzerFailed(_)){errors.push(format!("Owned worker stopped: {outcome:?}"));}}
  if errors.is_empty(){Ok(Value::Null)}else{let message=format!("{}; completed worker outcomes: {}; commit may have occurred",errors.join("; "),summaries.join(","));Err(abort(message,&sink))}
 })
}

#[cfg(test)] mod tests {
 use super::*; use serde_json::json; use std::{path::PathBuf,time::Duration};
 fn fixture()->(Analyses,Claim,Request){let mut state=Analyses::new();state.add(vec![json!({"checksum":"abc","filePath":"C:\\owned\\test.dem","source":"ebot","mapName":"de_test"})],None,Some(false),||"t".into()).unwrap();let claim=state.claim(1).unwrap();let req=Request{executable:PathBuf::from(r"C:\owned\csda.exe"),demo:PathBuf::from(r"C:\owned\test.dem"),output:PathBuf::from(r"C:\owned\out"),source:"ebot".into(),positions:false,deadline:Duration::from_secs(1)};(state,claim,req)}
 #[test] fn ordered_add_precedes_concurrent_remove(){use std::sync::{Arc,mpsc};let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let events=Arc::new(Mutex::new(Vec::<String>::new()));let(entered_tx,entered_rx)=mpsc::channel();let(release_tx,release_rx)=mpsc::channel();let st=state.clone();let ord=order.clone();let ev=events.clone();let add=thread::spawn(move||ordered(&st,&ord,|s|{let event=s.add(vec![json!({"checksum":"a","filePath":"C:\\owned\\a.dem","mapName":"de_x","source":"ebot"})],None,None,||"t".into())?.unwrap();Ok(((),Some(event)))},&mut|e|{entered_tx.send(()).unwrap();release_rx.recv().unwrap();ev.lock().unwrap().push(e["name"].as_str().unwrap().into());Ok(())}));entered_rx.recv().unwrap();let st=state.clone();let ord=order.clone();let ev=events.clone();let(attempt_tx,attempt_rx)=mpsc::channel();let(remove_done_tx,remove_done_rx)=mpsc::channel();let remove=thread::spawn(move||{attempt_tx.send(()).unwrap();let r=ordered(&st,&ord,|s|{s.remove(&["a"]);Ok(((),Some(json!({"name":"demos-removed-from-analyses","payload":["a"]}))))},&mut|e|{ev.lock().unwrap().push(e["name"].as_str().unwrap().into());Ok(())});remove_done_tx.send(()).unwrap();r});attempt_rx.recv().unwrap();assert!(remove_done_rx.try_recv().is_err());release_tx.send(()).unwrap();add.join().unwrap().unwrap();remove.join().unwrap().unwrap();assert_eq!(*events.lock().unwrap(),vec!["demos-added-to-analyses","demos-removed-from-analyses"]);assert!(state.lock().unwrap().all().is_empty());}
 #[test] fn reentry_and_cross_thread_wait_fail_without_deadlock(){use std::sync::Arc;let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let st=state.clone();let ord=order.clone();ordered(&state,&order,|_|Ok(((),Some(json!({"name":"probe"})))),&mut|_|{let same=ordered(&state,&order,|_|Ok(((),None)),&mut |_|Ok(()));assert!(same.unwrap_err().contains("Reentrant"));let next_state=st.clone();let next_order=ord.clone();let worker=thread::spawn(move||ordered(&next_state,&next_order,|_|Ok(((),None)),&mut |_|Ok(())));let error=worker.join().unwrap().unwrap_err();assert!(error.contains("timed out"));Ok(())}).unwrap();}
 #[test] fn positions_validate_independently(){assert!(positions_match(None,true));assert!(positions_match(Some(&Value::Null),false));assert!(positions_match(Some(&json!(true)),true));assert!(!positions_match(Some(&json!(true)),false));assert!(!positions_match(Some(&json!("bad")),false));}
 #[test] fn binds_claim_and_request(){let (state,claim,mut r)=fixture();let root=r.output.clone();assert!(valid_claim(&state,&claim,&r,&root,"test","abc"));assert!(!valid_claim(&state,&claim,&r,&root,"wrong","abc"));assert!(!valid_claim(&state,&claim,&r,&root,"test","other"));r.positions=true;assert!(!valid_claim(&state,&claim,&r,&root,"test","abc"));r.positions=false;r.demo=PathBuf::from(r"C:\owned\other.dem");assert!(!valid_claim(&state,&claim,&r,&root,"other","abc"));}
 #[test] fn importer_error_with_delivery_failure_reports_possible_commit(){for fail_at in [1,2]{let(mut state,claim,_)=fixture();let id=claim.run_id;assert!(state.begin_claim(&claim));let mut calls=0;let state=Mutex::new(state);let order=Mutex::new(());let result=import_failure(&state,&order,id,"database error".into(),&mut |_|{calls+=1;if calls==fail_at{Err("event failed".into())}else{Ok(())}});assert!(matches!(result,Outcome::DeliveryFailed{commit_may_have_occurred:true,..}));assert_eq!(calls,fail_at);}}
 #[test] fn centralized_completion_preserves_commit_certainty_and_late_worker(){let mut state=Analyses::new();let d=json!({"checksum":"same","filePath":"C:\\owned\\a.dem","source":"ebot","mapName":"m"});state.add(vec![d.clone(),d],None,None,||"t".into()).unwrap();let a=state.claim(2).unwrap();let b=state.claim(2).unwrap();assert!(state.begin_claim(&a));assert!(state.begin_claim(&b));let state=Mutex::new(state);let order=Mutex::new(());assert!(matches!(finalize(&state,&order,a.run_id,Outcome::Inserted(json!({}))),Outcome::Inserted(_)));assert!(state.lock().unwrap().append_output(b.run_id,"late").is_some());assert!(matches!(finalize(&state,&order,b.run_id,Outcome::ImportFailed{message:"unknown".into(),commit_may_have_occurred:true}),Outcome::ImportFailed{commit_may_have_occurred:true,..}));assert!(state.lock().unwrap().all().is_empty());}
 #[test] fn invalid_claim_cannot_finish_a_real_worker(){let(mut s,claim,_)=fixture();assert!(s.begin_claim(&claim));let state=Mutex::new(s);let order=Mutex::new(());assert!(matches!(finalize(&state,&order,claim.run_id,Outcome::InvalidClaim),Outcome::InvalidClaim));assert!(state.lock().unwrap().owns_started_claim(&claim));}
 #[test]fn original_numeric_settings_capacity(){for(value,expected)in[(json!(null),4),(json!(-1),0),(json!(0),0),(json!(1),1),(json!(2),2),(json!(2.5),3),(json!(8),8),(json!(10),8)]{assert_eq!(concurrency_limit(&json!({"analyze":{"maxConcurrentAnalyses":value}})).unwrap(),expected)}assert_eq!(concurrency_limit(&json!({"analyze":{}})).unwrap(),4);assert!(concurrency_limit(&json!({"analyze":{"maxConcurrentAnalyses":"2"}})).is_err());}
 #[test]fn uncertain_import_blocks_concurrent_followup_write(){use std::sync::{Arc,mpsc,atomic::{AtomicUsize,Ordering}};let gate=Arc::new(Mutex::new(false));let count=Arc::new(AtomicUsize::new(0));let(entered_tx,entered_rx)=mpsc::channel();let(release_tx,release_rx)=mpsc::channel();let g=gate.clone();let c=count.clone();let first=thread::spawn(move||guarded_import(Some(&g),||{c.fetch_add(1,Ordering::SeqCst);entered_tx.send(()).unwrap();release_rx.recv().unwrap();Outcome::ImportFailed{message:"commit unknown".into(),commit_may_have_occurred:true}}));entered_rx.recv().unwrap();let g=gate.clone();let c=count.clone();let second=thread::spawn(move||guarded_import(Some(&g),||{c.fetch_add(1,Ordering::SeqCst);Outcome::Inserted(json!({}))}));release_tx.send(()).unwrap();assert!(matches!(first.join().unwrap(),Outcome::ImportFailed{commit_may_have_occurred:true,..}));assert!(matches!(second.join().unwrap(),Outcome::ImportFailed{commit_may_have_occurred:false,..}));assert_eq!(count.load(Ordering::SeqCst),1);}
 #[test]fn panic_inside_import_poison_blocks_later_write(){use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};let gate=Arc::new(Mutex::new(false));let g=gate.clone();let worker=thread::spawn(move||guarded_import(Some(&g),||panic!("owned test panic")));assert!(worker.join().is_err());let calls=AtomicUsize::new(0);let result=guarded_import(Some(&gate),||{calls.fetch_add(1,Ordering::SeqCst);Outcome::Inserted(json!({}))});assert!(matches!(result,Outcome::ImportFailed{commit_may_have_occurred:true,..}));assert_eq!(calls.load(Ordering::SeqCst),0);}
 #[test]fn failed_finalize_after_success_blocks_followup_write(){use std::sync::{Arc,mpsc,atomic::{AtomicUsize,Ordering}};let gate=Arc::new(Mutex::new(false));let state=Arc::new(Mutex::new(Analyses::new()));let order=Arc::new(Mutex::new(()));let poison=order.clone();let _=thread::spawn(move||{let _g=poison.lock().unwrap();panic!("owned poison test")}).join();let count=Arc::new(AtomicUsize::new(0));let(entered_tx,entered_rx)=mpsc::channel();let(release_tx,release_rx)=mpsc::channel();let g=gate.clone();let st=state.clone();let ord=order.clone();let c=count.clone();let first=thread::spawn(move||guarded_import(Some(&g),||{c.fetch_add(1,Ordering::SeqCst);entered_tx.send(()).unwrap();release_rx.recv().unwrap();finalize(&st,&ord,7,Outcome::Inserted(json!({})))}));entered_rx.recv().unwrap();let g=gate.clone();let c=count.clone();let second=thread::spawn(move||guarded_import(Some(&g),||{c.fetch_add(1,Ordering::SeqCst);Outcome::Inserted(json!({}))}));release_tx.send(()).unwrap();assert!(matches!(first.join().unwrap(),Outcome::DeliveryFailed{commit_may_have_occurred:true,..}));assert!(matches!(second.join().unwrap(),Outcome::ImportFailed{commit_may_have_occurred:false,..}));assert_eq!(count.load(Ordering::SeqCst),1);}
 #[test] fn rejects_forgery_and_replay(){let(mut state,claim,r)=fixture();let root=r.output.clone();let mut altered=Claim{run_id:claim.run_id,analysis:claim.analysis.clone()};altered.analysis["demoChecksum"]=json!("other");assert!(!valid_claim(&state,&altered,&r,&root,"test","other"));altered.analysis=claim.analysis.clone();altered.analysis["analyzePositions"]=json!("bad");assert!(!valid_claim(&state,&altered,&r,&root,"test","abc"));assert!(state.begin_claim(&claim));assert!(!valid_claim(&state,&claim,&r,&root,"test","abc"));assert!(!state.begin_claim(&claim));}
}

pub fn analysis_positions(analysis:&Value,settings:&Value)->Result<bool,String>{match analysis.get("analyzePositions"){Some(Value::Bool(v))=>Ok(*v),Some(Value::Null)|None=>settings.get("analyze").and_then(|v|v.get("analyzePositions")).and_then(Value::as_bool).ok_or("Missing boolean analyzePositions setting".into()),Some(_)=>Err("Invalid analyzePositions override".into())}}
